{-| @Backend.Runtime.Kernel.Sort — sort indices in the order the interpreter's list sort
    produces, run for run and merge for merge. -}
module Pudu.Backend.Runtime.Kernel.Sort (sortKernelParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
sortKernelParts :: [(Text, [Text], [Text])]
sortKernelParts =
  [ ("sort_order", ["column_at", "float_decode"],
      [ "typedef struct { pudu_text data; int floats; } pudu_sort_order;"
      , "typedef struct { const int64_t *items; size_t length; } pudu_sort_run;"
      , "/* Whether row a's value compares greater than row b's. With floats this is"
      , "   \"neither less nor equal\", which holds whenever either is NaN. */"
      , "static int pudu_sort_gt(const pudu_sort_order *order, int64_t a, int64_t b) {"
      , "  uint64_t left = 0, right = 0;"
      , "  (void)pudu_column_at(order->data, a, &left);"
      , "  (void)pudu_column_at(order->data, b, &right);"
      , "  if (!order->floats) return left > right;"
      , "  return !(pudu_float_decode(left) < pudu_float_decode(right)) && !(pudu_float_decode(left) == pudu_float_decode(right));"
      , "}"
      ])
  , ("sort_merge", ["sort_order"],
      [ "/* The list sort's merges of two, three and four runs as one machine. Each"
      , "   state is one of its functions; the pending items x and y are heads already"
      , "   taken from their runs. Answers how many items it wrote. */"
      , "static size_t pudu_sort_merge(const pudu_sort_order *order, int ways, pudu_sort_run a, pudu_sort_run b, pudu_sort_run c, pudu_sort_run d, int64_t *out) {"
      , "  enum { TWO, THREE, THREE_X, THREE_Y, FOUR, FOUR_X, FOUR_Y, FOUR_XY } state = ways == 2 ? TWO : ways == 3 ? THREE : FOUR;"
      , "  int64_t x = 0, y = 0;"
      , "  size_t written = 0;"
      , "#define PUDU_SORT_TAKE(run) ((run).length -= 1, *(run).items++)"
      , "  for (;;) switch (state) {"
      , "    case TWO:"
      , "      while (a.length != 0 && b.length != 0)"
      , "        out[written++] = pudu_sort_gt(order, a.items[0], b.items[0]) ? PUDU_SORT_TAKE(b) : PUDU_SORT_TAKE(a);"
      , "      while (a.length != 0) out[written++] = PUDU_SORT_TAKE(a);"
      , "      while (b.length != 0) out[written++] = PUDU_SORT_TAKE(b);"
      , "      return written;"
      , "    case THREE:"
      , "      if (a.length == 0) { a = b; b = c; state = TWO; break; }"
      , "      if (b.length == 0) { b = c; state = TWO; break; }"
      , "      x = pudu_sort_gt(order, a.items[0], b.items[0]) ? PUDU_SORT_TAKE(b) : PUDU_SORT_TAKE(a);"
      , "      state = THREE_X;"
      , "      break;"
      , "    case THREE_X:"
      , "      if (c.length == 0) { out[written++] = x; state = TWO; break; }"
      , "      if (pudu_sort_gt(order, x, c.items[0])) out[written++] = PUDU_SORT_TAKE(c);"
      , "      else { out[written++] = x; state = THREE; }"
      , "      break;"
      , "    case THREE_Y:"
      , "      if (a.length == 0) { out[written++] = y; a = b; b = c; state = TWO; break; }"
      , "      if (pudu_sort_gt(order, a.items[0], y)) { out[written++] = y; state = THREE; }"
      , "      else out[written++] = PUDU_SORT_TAKE(a);"
      , "      break;"
      , "    case FOUR:"
      , "      if (a.length == 0) { a = b; b = c; c = d; state = THREE; break; }"
      , "      if (b.length == 0) { b = c; c = d; state = THREE; break; }"
      , "      x = pudu_sort_gt(order, a.items[0], b.items[0]) ? PUDU_SORT_TAKE(b) : PUDU_SORT_TAKE(a);"
      , "      state = FOUR_X;"
      , "      break;"
      , "    case FOUR_X:"
      , "      if (c.length == 0) { c = d; state = THREE_X; break; }"
      , "      if (d.length == 0) { state = THREE_X; break; }"
      , "      y = pudu_sort_gt(order, c.items[0], d.items[0]) ? PUDU_SORT_TAKE(d) : PUDU_SORT_TAKE(c);"
      , "      state = FOUR_XY;"
      , "      break;"
      , "    case FOUR_Y:"
      , "      if (b.length == 0) { b = c; c = d; state = THREE_Y; break; }"
      , "      if (a.length == 0) { a = b; b = c; c = d; state = THREE_Y; break; }"
      , "      x = pudu_sort_gt(order, a.items[0], b.items[0]) ? PUDU_SORT_TAKE(b) : PUDU_SORT_TAKE(a);"
      , "      state = FOUR_XY;"
      , "      break;"
      , "    case FOUR_XY:"
      , "      if (pudu_sort_gt(order, x, y)) { out[written++] = y; state = FOUR_X; }"
      , "      else { out[written++] = x; state = FOUR_Y; }"
      , "      break;"
      , "  }"
      , "#undef PUDU_SORT_TAKE"
      , "}"
      ])
  , ("sort_rows", ["sort_merge", "memory_failure"],
      [ "/* The reference list sort over row numbers: up to four items merge as"
      , "   single runs; otherwise ascending and strictly descending runs are found,"
      , "   then merged four at a time, with its special cases for two, three, five"
      , "   and six runs. The run after the last one found may be empty, and counts. */"
      , "static void pudu_sort_rows(const pudu_sort_order *order, int64_t *rows, size_t count) {"
      , "  static const pudu_sort_run none = {NULL, 0};"
      , "  int64_t *from, *to;"
      , "  size_t *bounds, *next, runs = 0;"
      , "  if (count < 2) return;"
      , "  if (count > SIZE_MAX / sizeof *from - 2) pudu_memory_failure();"
      , "  from = malloc(count * sizeof *from);"
      , "  to = malloc(count * sizeof *to);"
      , "  bounds = malloc((count + 2) * sizeof *bounds);"
      , "  next = malloc((count + 2) * sizeof *next);"
      , "  if (from == NULL || to == NULL || bounds == NULL || next == NULL) pudu_memory_failure();"
      , "  bounds[0] = 0;"
      , "  if (count <= 4) {"
      , "    memcpy(from, rows, count * sizeof *from);"
      , "    for (runs = 0; runs < count; ++runs) bounds[runs + 1] = runs + 1;"
      , "  } else {"
      , "    size_t at = 0, filled = 0;"
      , "    while (count - at >= 2) {"
      , "      size_t start = at;"
      , "      if (pudu_sort_gt(order, rows[at], rows[at + 1])) {"
      , "        at += 1;"
      , "        while (at + 1 < count && pudu_sort_gt(order, rows[at], rows[at + 1])) at += 1;"
      , "        at += 1;"
      , "        for (size_t index = at; index > start; --index) from[filled++] = rows[index - 1];"
      , "      } else {"
      , "        at += 1;"
      , "        while (at + 1 < count && !pudu_sort_gt(order, rows[at], rows[at + 1])) at += 1;"
      , "        at += 1;"
      , "        for (size_t index = start; index < at; ++index) from[filled++] = rows[index];"
      , "      }"
      , "      bounds[++runs] = filled;"
      , "    }"
      , "    while (at < count) from[filled++] = rows[at++];"
      , "    bounds[++runs] = filled;"
      , "  }"
      , "  while (runs > 1) {"
      , "    size_t made = 0, written = 0, done = 0;"
      , "    next[0] = 0;"
      , "#define PUDU_SORT_RUN(index) ((pudu_sort_run){from + bounds[index], bounds[(index) + 1] - bounds[index]})"
      , "    while (done < runs) {"
      , "      size_t left = runs - done, taken;"
      , "      if (left == 1) {"
      , "        size_t length = bounds[done + 1] - bounds[done];"
      , "        if (length != 0) memcpy(to + written, from + bounds[done], length * sizeof *to);"
      , "        written += length;"
      , "        taken = 1;"
      , "      } else if (left == 2 || left == 5) {"
      , "        written += pudu_sort_merge(order, 2, PUDU_SORT_RUN(done), PUDU_SORT_RUN(done + 1), none, none, to + written);"
      , "        taken = 2;"
      , "      } else if (left == 3 || left == 6) {"
      , "        written += pudu_sort_merge(order, 3, PUDU_SORT_RUN(done), PUDU_SORT_RUN(done + 1), PUDU_SORT_RUN(done + 2), none, to + written);"
      , "        taken = 3;"
      , "      } else {"
      , "        written += pudu_sort_merge(order, 4, PUDU_SORT_RUN(done), PUDU_SORT_RUN(done + 1), PUDU_SORT_RUN(done + 2), PUDU_SORT_RUN(done + 3), to + written);"
      , "        taken = 4;"
      , "      }"
      , "      done += taken;"
      , "      next[++made] = written;"
      , "    }"
      , "#undef PUDU_SORT_RUN"
      , "    { int64_t *swapped = from; size_t *held = bounds; from = to; to = swapped; bounds = next; next = held; }"
      , "    runs = made;"
      , "  }"
      , "  memcpy(rows, from, count * sizeof *rows);"
      , "  free(from);"
      , "  free(to);"
      , "  free(bounds);"
      , "  free(next);"
      , "}"
      ])
  , ("column_sort", ["sort_rows", "column_valid", "kernel_fresh", "kernel_put", "kernel_signed", "bytes_wrap", "text_literal", "memory_failure"],
      [ "/* Valid rows by value, then the invalid rows in row order, as packed words. */"
      , "static pudu_box *pudu_column_sort(pudu_box *data, pudu_box *validity, pudu_int rows, int floats) {"
      , "  int64_t count = pudu_kernel_signed(rows.bits);"
      , "  pudu_sort_order order = {data->fields[0].text, floats};"
      , "  unsigned char *bytes;"
      , "  pudu_text sorted;"
      , "  int64_t *valid;"
      , "  size_t kept = 0, written;"
      , "  if (count <= 0) return pudu_bytes_wrap(pudu_text_literal(\"\", 0));"
      , "  if ((uint64_t)count > SIZE_MAX / sizeof *valid) pudu_memory_failure();"
      , "  valid = malloc((size_t)count * sizeof *valid);"
      , "  if (valid == NULL) pudu_memory_failure();"
      , "  for (int64_t row = 0; row < count; ++row) if (pudu_column_valid(validity->fields[0].text, row)) valid[kept++] = row;"
      , "  pudu_sort_rows(&order, valid, kept);"
      , "  sorted = pudu_kernel_fresh((size_t)count * 8, &bytes);"
      , "  for (written = 0; written < kept; ++written) pudu_kernel_put(bytes + written * 8, (uint64_t)valid[written], 8);"
      , "  for (int64_t row = 0; row < count; ++row)"
      , "    if (!pudu_column_valid(validity->fields[0].text, row)) pudu_kernel_put(bytes + (written++) * 8, (uint64_t)row, 8);"
      , "  free(valid);"
      , "  return pudu_bytes_wrap(sorted);"
      , "}"
      ])
  ]
